import { gsap } from 'gsap';
import { Group } from 'three/webgpu';
import { vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const root = new Group();
  root.userData.handlers = {};
  const primitiveInstances = [];
  let gltfScene = null;
  let hoverTimeline = null;
  let clickTimeline = null;

  // Load GLB mesh
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gltfScene = gltf.scene;
      root.add(gltfScene);
    });
  }

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](root, prim.params || {});
      primitiveInstances.push(instance);
    }
  }

  // Hover effect: rise-in subtle (0.15 units)
  root.userData.handlers.hover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline({ defaults: { duration: 0.3, ease: 'power2.out' } });
    hoverTimeline.to(root.position, { y: root.position.y + 0.15 });
    hoverTimeline.to(root.position, { y: root.position.y, delay: 0.2 });
  };

  // Click effect: emit navigation event
  root.userData.handlers.click = () => {
    ctx.emit('hub-features.select', {});
  };

  // Cleanup resources
  root.userData.cleanup = () => {
    // Dispose GLB resources
    if (gltfScene) {
      gltfScene.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    }
    // Kill GSAP timelines
    if (hoverTimeline) hoverTimeline.kill();
    if (clickTimeline) clickTimeline.kill();
  };

  return root;
}
